import{_ as a,C as o,o as r,c as n,j as e,a as i,E as d,a6 as l}from"./chunks/framework.CCKCzdWs.js";const k=JSON.parse(`{"title":"Test card","description":"A test's card in VS Code's hover and on a click of its result icon in a JetBrains IDE: its latest runs as a strip, each linked to its run, how many passed, its median duration, its last failure, its owner, tags and quarantine.","frontmatter":{"title":"Test card","description":"A test's card in VS Code's hover and on a click of its result icon in a JetBrains IDE: its latest runs as a strip, each linked to its run, how many passed, its median duration, its last failure, its owner, tags and quarantine.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-test-card.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-test-card.html"}],["meta",{"property":"og:title","content":"Test card | Piwi for Playwright"}],["meta",{"property":"og:description","content":"A test's card in VS Code's hover and on a click of its result icon in a JetBrains IDE: its latest runs as a strip, each linked to its run, how many passed, its median duration, its last failure, its owner, tags and quarantine."}]]},"headers":[],"relativePath":"features/editor-test-card.md","filePath":"features/editor-test-card.md","lastUpdated":1794786286000}`),h={name:"features/editor-test-card.md"};function c(u,t,p,f,m,w){const s=o("Needs");return r(),n("div",null,[t[0]||(t[0]=e("h1",{id:"test-card",tabindex:"-1"},[i("Test card "),e("a",{class:"header-anchor",href:"#test-card","aria-label":'Permalink to "Test card"'},"​")],-1)),d(s,{editor:""}),t[1]||(t[1]=l('<p>A test&#39;s card answers &quot;my bug or a flake?&quot; without leaving the editor. In VS Code it is the test&#39;s hover on its <code>test(…)</code> line; in a JetBrains IDE, a click on the test&#39;s result icon opens it.</p><h2 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h2><ul><li><strong>The strip</strong>: the test&#39;s latest runs, oldest on the left, as the dashboard&#39;s test row draws them: <code>✓</code> passed, <code>✗</code> failed, <code>◐</code> flaky (it passed on a retry), <code>○</code> skipped. A run is one mark, whatever its retries, repetitions and projects: failed when one of them ended failed, flaky when one passed on a retry. Each mark links to its run, and its tooltip names the run, the outcome and how long the test took.</li><li><strong>How far back</strong>: twenty runs at most, read from the test&#39;s last 50 attempts, so a test run in three projects shows about sixteen, and one run with <code>--repeat-each</code> fewer still. The dashboard&#39;s test page holds its whole history.</li><li><strong>How they went</strong>: <code>Passed 17 of the last 20 runs · 2 flaky · median 1.4 s</code>, skipped runs left out.</li><li><strong>The last failure</strong>: the run it failed in, how long ago, and the first line of its error.</li><li><strong>Its owner, tags and quarantine</strong>: the owner its <code>piwi:owner</code> annotation names, its Playwright tags, and, while it is <a href="./flaky-tests.html#quarantine-with-a-way-out">quarantined</a>, for how long and how many passes it has toward release.</li></ul><p>Under the card, <strong>Run</strong> runs the test, <strong>Open in dashboard</strong> opens its page, and <strong>More…</strong> opens the test&#39;s actions: <a href="./editor-runs.html">Runs from the editor</a> lists them.</p><h2 id="where-it-comes-from" tabindex="-1">Where it comes from <a class="header-anchor" href="#where-it-comes-from" aria-label="Permalink to &quot;Where it comes from&quot;">​</a></h2><p>The editor reads the test&#39;s history from the instance as the card opens, and keeps it for 30 seconds. It waits for it one and a half seconds at most: past that, the hover shows the test&#39;s result in one line, and a click in a JetBrains IDE opens the test&#39;s actions. A test the instance does not know yet has no card.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-runs.html">Runs from the editor</a></li><li><a href="./flaky-tests.html">Flaky tests</a></li></ul>',8))])}const y=a(h,[["render",c]]);export{k as __pageData,y as default};
